// Interactive success-vs-object-count charts, drawn as inline SVG from window.WAVE_DATA
// (static/js/data.js, generated by scripts/build_data.py).
(function () {
  'use strict';

  var NS = 'http://www.w3.org/2000/svg';
  var W = 900, H = 340;
  var M = { top: 26, right: 16, bottom: 46, left: 52 };
  var PW = W - M.left - M.right, PH = H - M.top - M.bottom;

  // Training range (1..N_train) per task, from the paper's appendix.
  var TRAIN = { tower3: 7, tower6: 7, line: 6, pyramid: 6, square: 9, wall: 8 };
  var TASK_NAMES = { tower3: 'cube stacking (h=3)', square: 'square', pyramid: 'pyramid', line: 'line' };

  function el(tag, attrs, parent) {
    var node = document.createElementNS(NS, tag);
    for (var k in attrs) node.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(node);
    return node;
  }

  function fmt(v) { return v.toFixed(2); }

  function render(container, series, opts) {
    container.innerHTML = '';
    container.classList.remove('in-view', 'has-focus');
    var xMax = opts.xMax || 30;
    var x = function (n) { return M.left + ((n - 1) / (xMax - 1)) * PW; };
    var y = function (v) { return M.top + (1 - v) * PH; };

    var svg = el('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img', 'aria-label': opts.aria || 'success against object count' }, container);

    if (opts.train) {
      var x0 = x(1) - 6, x1 = x(opts.train) + (x(2) - x(1)) / 2;
      el('rect', { class: 'train-band', x: x0, y: M.top, width: x1 - x0, height: PH }, svg);
      var tl = el('text', { class: 'train-label', x: x0 + 6, y: M.top - 8 }, svg);
      tl.textContent = opts.trainLabel || 'training range';
    }

    var grid = el('g', { class: 'grid' }, svg);
    var axis = el('g', { class: 'axis' }, svg);
    [0, 0.25, 0.5, 0.75, 1].forEach(function (v) {
      el('line', { x1: M.left, x2: W - M.right, y1: y(v), y2: y(v) }, grid);
      var t = el('text', { x: M.left - 8, y: y(v) + 4, 'text-anchor': 'end' }, axis);
      t.textContent = v.toFixed(2);
    });
    var step = xMax > 15 ? 5 : xMax > 10 ? 2 : 1;
    for (var n = 1; n <= xMax; n++) {
      if (n !== 1 && n % step !== 0) continue;
      var t = el('text', { x: x(n), y: H - M.bottom + 18, 'text-anchor': 'middle' }, axis);
      t.textContent = n;
    }
    el('line', { class: 'baseline', x1: M.left, x2: W - M.right, y1: y(0), y2: y(0) }, svg);
    var xt = el('text', { class: 'axis-title', x: M.left + PW / 2, y: H - 6, 'text-anchor': 'middle' }, svg);
    xt.textContent = 'object count N';
    var yt = el('text', { class: 'axis-title', transform: 'rotate(-90)', x: -(M.top + PH / 2), y: 14, 'text-anchor': 'middle' }, svg);
    yt.textContent = 'whole-task success';

    // Draw back to front so the first series (WAVE) sits on top.
    var groups = [];
    series.slice().reverse().forEach(function (s) {
      var pts = s.pts.filter(function (p) { return p[0] <= xMax; });
      var g = el('g', { class: 'series draw' + (s.published ? ' is-published' : '') + (s.dash ? ' is-dashed' : '') }, svg);
      var hasBand = pts.length > 1 && pts.every(function (p) { return p[2] !== null && p[3] !== null; });
      if (hasBand && !s.published) {
        var top = pts.map(function (p, i) { return (i ? 'L' : 'M') + x(p[0]) + ',' + y(p[3]); }).join('');
        var bot = pts.slice().reverse().map(function (p) { return 'L' + x(p[0]) + ',' + y(p[2]); }).join('');
        el('path', { class: 'band', d: top + bot + 'Z', fill: s.color }, g);
      }
      if (pts.length > 1) {
        var d = pts.map(function (p, i) { return (i ? 'L' : 'M') + x(p[0]) + ',' + y(p[1]); }).join('');
        var path = el('path', { class: 'line', d: d, stroke: s.color }, g);
        g.style.setProperty('--len', Math.ceil(path.getTotalLength ? path.getTotalLength() : 2000) + 1);
      }
      if (s.published || pts.length <= xMax / 2 && pts.length < 8) {
        pts.forEach(function (p) {
          el('rect', { x: x(p[0]) - 3.5, y: y(p[1]) - 3.5, width: 7, height: 7, fill: s.color,
                       transform: 'rotate(45 ' + x(p[0]) + ' ' + y(p[1]) + ')', stroke: '#fff' }, g);
        });
      } else {
        pts.forEach(function (p) { el('circle', { cx: x(p[0]), cy: y(p[1]), r: 2.6, fill: s.color }, g); });
      }
      groups.unshift({ s: s, g: g, pts: pts });
    });

    // Direct labels at the paper's positions (with a leader line when there is an anchor point),
    // drawn above every series so no line crosses them.
    var labelLayer = el('g', { class: 'draw' }, svg);
    groups.forEach(function (it) {
      var p = it.s.label_pos;
      if (!p) return;
      var lg = el('g', {}, labelLayer), lx = x(p[0]), ly = y(p[1]);
      if (p[2]) el('line', { class: 'series-label-leader', x1: x(p[2][0]), y1: y(p[2][1]), x2: lx - 3, y2: ly }, lg);
      el('text', { class: 'series-label', x: lx, y: ly, 'dominant-baseline': 'central' }, lg).textContent = it.s.label;
      it.label = lg;
    });

    // Legend: one entry per series, published methods collapsed into one toggle.
    var legend = document.createElement('div');
    legend.className = 'chart-legend';
    var entries = [];
    groups.forEach(function (it) {
      var key = it.s.published ? 'published' : it.s.key;
      var entry = entries.filter(function (e) { return e.key === key; })[0];
      if (!entry) {
        entry = { key: key, label: it.s.published ? 'published methods (own tasks)' : it.s.label,
                  color: it.s.color, dashed: it.s.published || it.s.dash, items: [] };
        entries.push(entry);
      }
      entry.items.push(it);
    });
    entries.forEach(function (e) {
      var b = document.createElement('button');
      b.type = 'button';
      b.setAttribute('aria-pressed', 'true');
      b.innerHTML = '<span class="swatch' + (e.dashed ? ' is-dashed' : '') + '" style="background:' + e.color +
        ';color:' + e.color + '"></span>' + e.label;
      b.addEventListener('click', function () {
        var off = b.classList.toggle('is-off');
        b.setAttribute('aria-pressed', String(!off));
        e.items.forEach(function (it) {
          it.g.classList.toggle('is-hidden', off); it.hidden = off;
          if (it.label) it.label.style.display = off ? 'none' : '';
        });
      });
      b.addEventListener('mouseenter', function () {
        container.classList.add('has-focus');
        e.items.forEach(function (it) { it.g.classList.add('is-focus'); });
      });
      b.addEventListener('mouseleave', function () {
        container.classList.remove('has-focus');
        e.items.forEach(function (it) { it.g.classList.remove('is-focus'); });
      });
      legend.appendChild(b);
    });
    container.appendChild(legend);

    // Hover: crosshair at the nearest count and a tooltip with every visible value there.
    var cross = el('line', { class: 'crosshair', y1: M.top, y2: M.top + PH, visibility: 'hidden' }, svg);
    var hit = el('rect', { x: M.left, y: M.top, width: PW, height: PH, fill: 'transparent' }, svg);
    var tip = document.createElement('div');
    tip.className = 'chart-tooltip';
    container.appendChild(tip);

    function move(evt) {
      var r = svg.getBoundingClientRect();
      var px = (evt.clientX - r.left) * (W / r.width);
      var n = Math.max(1, Math.min(xMax, Math.round(1 + ((px - M.left) / PW) * (xMax - 1))));
      var rows = [];
      groups.forEach(function (it) {
        if (it.hidden) return;
        var p = it.pts.filter(function (q) { return q[0] === n; })[0];
        if (p) rows.push({ s: it.s, p: p });
      });
      if (!rows.length) { leave(); return; }
      rows.sort(function (a, b) { return b.p[1] - a.p[1]; });
      cross.setAttribute('x1', x(n)); cross.setAttribute('x2', x(n));
      cross.setAttribute('visibility', 'visible');
      tip.innerHTML = '<div class="tt-head">N = ' + n + (opts.train && n > opts.train ? ' <span class="tt-range">beyond training</span>' : '') + '</div>' +
        rows.map(function (row) {
          var range = row.p[2] !== null && row.p[3] !== null && row.p[2] !== row.p[3]
            ? '<span class="tt-range">' + fmt(row.p[2]) + '–' + fmt(row.p[3]) + '</span>' : '';
          return '<div class="tt-row"><span class="tt-swatch" style="background:' + row.s.color + '"></span>' +
            row.s.label + '<span class="tt-val">' + fmt(row.p[1]) + '</span>' + range + '</div>';
        }).join('');
      tip.classList.add('is-visible');
      var cw = container.clientWidth, tw = tip.offsetWidth;
      var left = (x(n) / W) * r.width + 14;
      if (left + tw > cw) left = (x(n) / W) * r.width - tw - 14;
      tip.style.left = Math.max(0, left) + 'px';
      tip.style.top = Math.max(0, (evt.clientY - container.getBoundingClientRect().top) - 30) + 'px';
    }
    function leave() { cross.setAttribute('visibility', 'hidden'); tip.classList.remove('is-visible'); }
    hit.addEventListener('mousemove', move);
    hit.addEventListener('mouseleave', leave);
    hit.addEventListener('touchstart', function (e) { move(e.touches[0]); }, { passive: true });
    hit.addEventListener('touchmove', function (e) { move(e.touches[0]); }, { passive: true });

    reveal(container);
  }

  function reveal(container) {
    if (!('IntersectionObserver' in window)) { container.classList.add('in-view'); return; }
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { container.classList.add('in-view'); io.disconnect(); }
      });
    }, { threshold: 0.25 });
    // Wait a frame so the stroke-dashoffset start state is painted before the transition.
    requestAnimationFrame(function () { io.observe(container); });
  }

  function tabs(root, name, onPick) {
    var buttons = root.querySelectorAll('[data-' + name + ']');
    Array.prototype.forEach.call(buttons, function (b) {
      b.addEventListener('click', function () {
        Array.prototype.forEach.call(buttons, function (o) { o.classList.toggle('is-dark', o === b); });
        onPick(b.getAttribute('data-' + name));
      });
    });
  }

  function init() {
    var D = window.WAVE_DATA;
    if (!D) return;

    var gantry = document.querySelector('[data-chart="gantry"]');
    if (gantry) render(gantry, D.gantry, { train: 7, trainLabel: 'training range (stacking)', aria: 'WAVE success on the gantry against object count' });

    var panda = document.querySelector('[data-chart="panda"]');
    if (panda) render(panda, D.panda, { train: 6, trainLabel: 'trained on every task', aria: 'WAVE success on the Panda arm against object count' });

    var bl = document.querySelector('[data-chart="baselines"]');
    if (bl) {
      var drawBl = function (task) {
        render(bl, D.baselines[task], { train: TRAIN[task], trainLabel: 'training range', aria: 'baselines on ' + task });
      };
      tabs(document.getElementById('baseline-tabs'), 'task', drawBl);
      drawBl('tower3');
    }

    var ab = document.querySelector('[data-chart="ablations"]');
    if (ab) {
      var state = { kind: 'side', task: 'tower3' };
      var drawAb = function () {
        render(ab, D.ablations[state.kind][state.task], { train: TRAIN[state.task], trainLabel: 'training range',
          aria: 'ablation ' + state.kind + ' on ' + TASK_NAMES[state.task] });
      };
      tabs(document.getElementById('ablation-kind'), 'kind', function (k) { state.kind = k; drawAb(); });
      tabs(document.getElementById('ablation-task'), 'task', function (t) { state.task = t; drawAb(); });
      drawAb();
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
